<script setup>
import { onMounted, reactive, ref } from 'vue'; import { listUsers, actionUser, deleteUser, downloadTemplate, importUsers } from '@/api/admin'; import { departments } from '@/api/auth'
const users=ref([]), deps=ref([]), loading=ref(false), error=ref(''); const filters=reactive({name:'',department_id:'',position:'',account_status:'',register_status:''}); const page=ref(1); const total=ref(0); const file=ref(null)
async function load(){loading.value=true;error.value='';try{const r=await listUsers({...filters,page:page.value});users.value=r.data.results;total.value=r.data.count}catch(e){error.value=e.response?.data?.detail||'加载失败'}finally{loading.value=false}} onMounted(async()=>{deps.value=(await departments()).data;load()});function ask(text){return window.confirm(text)} async function act(u,a,data={}){if(!ask(`确认执行${a}操作？`))return;try{await actionUser(u.id,a,data);load()}catch(e){error.value=e.response?.data?.detail||'操作失败'}} async function remove(u){if(ask('确认逻辑删除该用户？')){await deleteUser(u.id);load()}} async function template(){const r=await downloadTemplate();const a=document.createElement('a');a.href=URL.createObjectURL(r.data);a.download='users_template.xlsx';a.click();URL.revokeObjectURL(a.href)} async function upload(){if(!file.value)return;const r=await importUsers(file.value);window.alert(`成功 ${r.data.success_count} 行，共 ${r.data.total} 行`);load()}
</script>
<template><section><div class="panel"><p class="eyebrow">SYSTEM / USERS</p><h1>系统管理中心</h1><div class="actions"><input v-model="filters.name" placeholder="按姓名查询"/><select v-model="filters.department_id"><option value="">全部部门</option><option v-for="d in deps" :value="d.id">{{d.name}}</option></select><select v-model="filters.account_status"><option value="">账号状态</option><option value="enabled">启用</option><option value="disabled">禁用</option></select><button @click="page=1;load">查询</button><button @click="template">下载模板</button><input type="file" accept=".xlsx" @change="file=$event.target.files[0]"/><button @click="upload">批量导入</button></div><p v-if="loading" class="muted">加载中…</p><p v-if="error" class="error">{{error}}</p><div v-if="!loading&&!users.length" class="muted">暂无数据</div><div class="table-wrap" v-else><table><thead><tr><th>姓名</th><th>职位</th><th>部门</th><th>岗位</th><th>账号</th><th>审核</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}</td><td>{{u.position}}</td><td>{{u.department?.name}}</td><td>{{u.job_title||'无'}}</td><td>{{u.account_status}}</td><td>{{u.register_status}}</td><td class="actions"><button v-if="u.account_status==='disabled'" @click="act(u,'enable')">启用</button><button v-else @click="act(u,'disable')">禁用</button><button class="danger" @click="remove(u)">删除</button></td></tr></tbody></table></div><p class="muted">共 {{total}} 条</p></div></section></template>
